func (m *MatterMutation) WhereP(ps ...func(*sql.Selector)) {
	p := make([]predicate.Matter, len(ps))
	for i := range ps {
		p[i] = ps[i]
	}
	m.Where(p...)
}

// Op returns the operation name.
func (m *MatterMutation) Op() Op {
	return m.op
}

// SetOp allows setting the mutation operation.
func (m *MatterMutation) SetOp(op Op) {
	m.op = op
}

// Type returns the node type of this mutation (Matter).
func (m *MatterMutation) Type() string {
	return m.typ
}

// Fields returns all fields that were changed during this mutation. Note that in
// order to get all numeric fields that were incremented/decremented, call
// AddedFields().
func (m *MatterMutation) Fields() []string {
	fields := make([]string, 0, 5)
	if m.client != nil {
		fields = append(fields, matter.FieldClientID)
	}
	if m.practice_area != nil {
		fields = append(fields, matter.FieldPracticeArea)
	}
	if m.status != nil {
		fields = append(fields, matter.FieldStatus)
	}
	if m.opened_at != nil {
		fields = append(fields, matter.FieldOpenedAt)
	}
	if m.lead_partner_id != nil {
		fields = append(fields, matter.FieldLeadPartnerID)
	}
	return fields
}

// Field returns the value of a field with the given name. The second boolean
// return value indicates that this field was not set, or was not defined in the
// schema.
func (m *MatterMutation) Field(name string) (ent.Value, bool) {
	switch name {
	case matter.FieldClientID:
		return m.ClientID()
	case matter.FieldPracticeArea:
		return m.PracticeArea()
	case matter.FieldStatus:
		return m.Status()
	case matter.FieldOpenedAt:
		return m.OpenedAt()
	case matter.FieldLeadPartnerID:
		return m.LeadPartnerID()
	}
	return nil, false
}

// OldField returns the old value of the field from the database. An error is
// returned if the mutation operation is not UpdateOne, or the query to the
// database failed.
func (m *MatterMutation) OldField(ctx context.Context, name string) (ent.Value, error) {
	switch name {
	case matter.FieldClientID:
		return m.OldClientID(ctx)
	case matter.FieldPracticeArea:
		return m.OldPracticeArea(ctx)
	case matter.FieldStatus:
		return m.OldStatus(ctx)
	case matter.FieldOpenedAt:
		return m.OldOpenedAt(ctx)
	case matter.FieldLeadPartnerID:
		return m.OldLeadPartnerID(ctx)
	}
	return nil, fmt.Errorf("unknown Matter field %s", name)
}

// SetField sets the value of a field with the given name. It returns an error if
// the field is not defined in the schema, or if the type mismatched the field
// type.
func (m *MatterMutation) SetField(name string, value ent.Value) error {
	switch name {
	case matter.FieldClientID:
		v, ok := value.(string)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetClientID(v)
		return nil
	case matter.FieldPracticeArea:
		v, ok := value.(string)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetPracticeArea(v)
		return nil
	case matter.FieldStatus:
		v, ok := value.(string)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetStatus(v)
		return nil
	case matter.FieldOpenedAt:
		v, ok := value.(time.Time)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetOpenedAt(v)
		return nil
	case matter.FieldLeadPartnerID:
		v, ok := value.(string)
		if !ok {
			return fmt.Errorf("unexpected type %T for field %s", value, name)
		}
		m.SetLeadPartnerID(v)
		return nil
	}
	return fmt.Errorf("unknown Matter field %s", name)
}

